from pysat.formula import CNF
from pysat.solvers import Solver

# Langford sequence L(2,7): length 14, values 1-7, each appearing twice
# Constraint: the two copies of value v are exactly v+1 positions apart
# (i.e., if v is at position i, the other copy is at position i+v+1)

# Let's use a direct backtracking search first
def solve_langford(n=7):
    length = 2 * n
    seq = [0] * length
    used = [False] * (n + 1)  # used[v] = True if v has been placed

    def backtrack(pos):
        if pos == length:
            return all(used[v] for v in range(1, n+1))

        if seq[pos] != 0:
            return backtrack(pos + 1)

        for v in range(1, n + 1):
            if not used[v]:
                # Place v at pos and pos + v + 1
                other = pos + v + 1
                if other < length and seq[other] == 0:
                    seq[pos] = v
                    seq[other] = v
                    used[v] = True
                    if backtrack(pos + 1):
                        return True
                    seq[pos] = 0
                    seq[other] = 0
                    used[v] = False

        return False

    if backtrack(0):
        return seq
    return None

result = solve_langford(7)
print("Solution:", result)

# Verify
if result:
    n = 7
    print("Verification:")
    for v in range(1, n+1):
        positions = [i for i, x in enumerate(result) if x == v]
        print(f"  Value {v}: positions {positions}, gap = {positions[1] - positions[0]} (expected {v+1})")
    print("All values present:", sorted(result) == sorted(list(range(1,8))*2))
